func CVDisplayLinkSetOutputHandler(displayLink unsafe.Pointer, handler func(unsafe.Pointer, *CVTimeStamp, *CVTimeStamp, uint64, *uint64) int32) int32 {
	var __block_handler objc.Block
	if handler != nil {
		__block_handler = objc.NewBlock(func(_ objc.Block, blockParam0 unsafe.Pointer, blockParam1 *CVTimeStamp, blockParam2 *CVTimeStamp, blockParam3 uint64, blockParam4 *uint64) int32 {
			return handler(blockParam0, blockParam1, blockParam2, blockParam3, blockParam4)
		})
		defer __block_handler.Release()
	}
	return _fnCVDisplayLinkSetOutputHandler(displayLink, __block_handler)
}

